// Esse código não lê nem altera o conteúdo do notebook: apenas mostra os nomes dos campos recebidos e identifica em quais propriedades binárias os arquivos chegaram.

return items.map((item) => ({
  json: {
    camposRecebidos: Object.keys(item.json),
    arquivosRecebidos: Object.keys(item.binary ?? {}),
  },
  binary: item.binary,
}));

// Separar cada célula do notebook em um item.
//Identificar se é uma célula de código ou de texto (markdown).
//Extrair o conteúdo de cada célula.
//Preservar os resultados armazenados, inclusive saídas que possam conter tabelas, textos e gráficos.

const notebook = $input.first().json.data;

if (!notebook || !Array.isArray(notebook.cells)) {
  throw new Error('Não encontrei as células do notebook.');
}

return notebook.cells.map((cell, index) => {
  const conteudo = Array.isArray(cell.source)
    ? cell.source.join('')
    : (cell.source ?? '');

  return {
    json: {
      indice: index,
      tipo: cell.cell_type,
      conteudo,
      resultados: cell.outputs ?? []
    }
  };
});

// reunir as 14 células em um único texto, preservando a separação entre texto explicativo, código e resultados.

const celulas = $input.all();

const texto = celulas.map(({ json }) => {
  const tipo = json.tipo === 'markdown'
    ? 'TEXTO'
    : 'CÓDIGO';

  const resultados = (json.resultados ?? [])
    .map((r) => {
      const dados = r.data ?? {};
      const textoSaida = [
        ...(r.text ?? []),
        ...(dados['text/plain'] ?? []),
        ...(dados['text/html'] ?? [])
      ];

      return textoSaida.join('');
    })
    .filter(Boolean)
    .join('\n');

  return [
    `--- CÉLULA ${json.indice} (${tipo}) ---`,
    json.conteudo ?? '',
    resultados ? `RESULTADOS:\n${resultados}` : ''
  ].filter(Boolean).join('\n');
}).join('\n\n');

return [{
  json: {
    totalCelulas: celulas.length,
    conteudoNotebook: texto
  }
}];

// Deve receber os dados do nó Dados Arduino, que já gera 50 itens.

const registros = $input.all().map(item => item.json);

const grupos = {};

for (const registro of registros) {
  const massa = Number(registro.peso_padrao);
  const leitura = Number(registro.leitura);

  if (!Number.isFinite(massa) || !Number.isFinite(leitura)) {
    continue;
  }

  if (!grupos[massa]) {
    grupos[massa] = [];
  }

  grupos[massa].push(leitura);
}

const estatisticas = Object.entries(grupos).map(([massa, valores]) => {
  const media = valores.reduce((soma, valor) => soma + valor, 0)
    / valores.length;

  const variancia = valores.reduce(
    (soma, valor) => soma + (valor - media) ** 2,
    0
  ) / valores.length;


  return {
    peso_padrao: Number(massa),
    quantidade_arduino: valores.length,
    media_arduino: media,
    desvio_padrao_arduino: Math.sqrt(variancia),
    minimo_arduino: Math.min(...valores),
    maximo_arduino: Math.max(...valores)
  };
});

return estatisticas.map(item => ({ json: item }));

// Deve receber os dados do nó Dados Quantum, que já gera 50 itens.

const registros = $input.all().map(item => item.json);

const grupos = {};

for (const registro of registros) {
  const massa = Number(registro.peso_padrao);
  const leitura = Number(registro.leitura);

  if (!Number.isFinite(massa) || !Number.isFinite(leitura)) {
    continue;
  }

  if (!grupos[massa]) {
    grupos[massa] = [];
  }

  grupos[massa].push(leitura);
}

const estatisticas = Object.entries(grupos).map(([massa, valores]) => {
  const media = valores.reduce((soma, valor) => soma + valor, 0)
    / valores.length;

  const variancia = valores.reduce(
    (soma, valor) => soma + (valor - media) ** 2,
    0
  ) / valores.length;


  return {
    peso_padrao: Number(massa),
    quantidade_quantum: valores.length,
    media_quantum: media,
    desvio_padrao_quantum: Math.sqrt(variancia),
    minimo_quantum: Math.min(...valores),
    maximo_quantum: Math.max(...valores)
  };
});

return estatisticas.map(item => ({ json: item }));

// calcular a diferença entre as médias para cada massa.


const registros = $input.all();

return registros.map(({ json }) => {
  const diferenca = json.media_arduino - json.media_quantum;

  return {
    json: {
      ...json,
      diferenca_g: diferenca,
      diferenca_absoluta_g: Math.abs(diferenca),
      diferenca_relativa_percentual:
        json.media_quantum !== 0
          ? (diferenca / json.media_quantum) * 100
          : null
    }
  };
});

// Organizar os resultados em um único bloco de texto, que depois enviaremos para a IA interpretar.

const registros = $input.all().map(item => item.json);

const dados = registros.map(r => ({
  massa_g: r.peso_padrao,
  media_arduino: r.media_arduino,
  media_quantum: r.media_quantum,
  desvio_padrao_arduino: r.desvio_padrao_arduino,
  desvio_padrao_quantum: r.desvio_padrao_quantum,
  diferenca_g: r.diferenca_g,
  diferenca_absoluta_g: r.diferenca_absoluta_g,
  diferenca_relativa_percentual: r.diferenca_relativa_percentual
}));

return [{
  json: {
    quantidade_pontos: dados.length,
    dados_comparativos: dados,
    texto_para_analise: JSON.stringify(dados, null, 2)
  }
}];
